from sqlalchemy.ext.asyncio import AsyncSessionfrom base.exceptions import EntityBadRequestErrorfrom base.service import BaseServicefrom post.utils import generate_slugfrom reaction.service import ReactionServicefrom topic.offrer.model import TopicOffer, TopicOfferStatusfrom topic.release.schemas import (AddTopicByOffer, CreateTopic,                                  )from user.model import User, UserRoleEnumfrom user.service import UserServicefrom container.service import ContainerServicefrom container.model import Container, ContainerTypefrom container.repository import ContainerRepositoryfrom container.schemas import FullContainerShowfrom base.exceptions import InsufficientPermissionsErrorfrom topic.offrer.service import TopicOfferServiceclass TopicService(BaseService[Container, ContainerRepository]):    def __init__(self, session: AsyncSession):        super().__init__(Container, session, ContainerRepository)        self.offer_service = TopicOfferService(session)        self.user_service = UserService(session)        self.reaction_service = ReactionService(session)        self.container_service = ContainerService(session, type=ContainerType.topic)    async def create_topic(            self,            topic: CreateTopic,            author: User,            from_offer: bool = False    ) -> Container:        if author.role < UserRoleEnum.MODERATOR and not from_offer:            raise InsufficientPermissionsError()        topic.slug = generate_slug(topic.slug)        await self.check_already_exists(slug=topic.slug, type=ContainerType.topic)        topic = await self.container_service.create_container(            **topic.dict(),            author_id=author.id        )        return topic    async def create_topic_from_offer(            self,            topic_offer: TopicOffer,            process: AddTopicByOffer,            process_user: User    ) -> TopicOffer:        if topic_offer.status != TopicOfferStatus.PENDING:            raise EntityBadRequestError(                "offer-Тема", f"Предложенная тема уже имеет статус {topic_offer.status}"            )        await self.offer_service.update_item(            topic_offer,            status=process.status,            process_user_id=process_user.id        )        if process.status == TopicOfferStatus.APPROVE:            slug = generate_slug(process.slug)            title = process.title or topic_offer.title            description = process.description or topic_offer.description            topic = CreateTopic(                title=title,                description=description,                slug=slug            )            release_topic = await self.create_topic(                topic=topic, author=topic_offer.author, from_offer=True            )            await self.offer_service.update_item(                topic_offer,                release_topic_id=release_topic.id            )        return topic_offer